"""
WARP v0.5.0 - build hook.  Emits warp_pkg.vhd (pure Python, no dependencies).

Fitted to the source photo (WIN_20230909_23_29_18) in .heirloom_work/rb_warp (dfit4.py / protof.py):

  MAP      120 x 136 knots, 4 bits: the warp phase D (1/16 cycle) added to the perspective carrier,
           one knot every 16 virtual px across and 8 virtual lines down.  Sign-consistent fit (dfit11.py):
           seeded by coherent demodulation of the photo's R against the carrier, refined on R, G and B
           jointly with the full-cycle palette, anchored to the demodulated phase, wrap-aware smoothing.  Split into even rows (C_ME) and odd rows (C_MO),
           8192 x 4 each, so the per-line engine reads both neighbour rows at once.
  C_PAL_*  1024 x 8 (Y, U, V): 8 palettes x 2 halves (above / below the horizon) x 64 phase steps over
           the FULL cycle of P.  Palette 0 = the photo: per-phase MODE colours of the photo over the fitted
           phase (dfit11.py), green -> teal -> lavender -> orange -> olive -> lavender -> green above,
           redder orange and violet below; 1..7 are transforms of it.  Y and chroma are 10-bit / 4, U/V in
           the hardware convention (U = Cr), luma pre-boosted 16/13.
  C_HZ     34 x 6: the green haze down the frame (G drop, 0..62) per 32 virtual lines.
  C_ED     68 x 6: the left margin's staircase edge / 4 per 16 virtual lines.
  C_MG_*   64 x 8: the margin's green ramp (0, G, 0) per 4 virtual px.
  C_KA/KB  64 x 18: carrier gains kd * 2^32 / 60000 and kd * 2^32 / 96000, kd = 2^((K1 - 512) / 512).
  C_T_*    16 entries per timing ID: virtual-line step (Q.8), pixel step (Q.4), SD start, osc/zigzag steps.
"""
import os
HERE = os.path.dirname(os.path.abspath(__file__))
# the fitted full-cycle Warp palettes (rgb, haze-corrected), above / below the horizon, 64 phase steps
PAL_UP = [[12, 154, 14], [12, 167, 15], [14, 167, 18], [20, 166, 27], [28, 165, 41], [36, 160, 61], [49, 151, 88], [61, 144, 110], [68, 142, 120], [78, 141, 136], [88, 139, 153], [94, 137, 162], [99, 136, 171], [104, 136, 178], [110, 134, 180], [117, 133, 181], [123, 132, 176], [130, 131, 168], [136, 129, 159], [142, 129, 148], [148, 128, 126], [156, 127, 97], [165, 127, 77], [174, 127, 54], [185, 129, 24], [195, 129, 10], [200, 128, 6], [204, 128, 5], [208, 128, 3], [213, 128, 2], [216, 127, 2], [218, 127, 2], [220, 127, 2], [220, 127, 2], [219, 127, 2], [216, 127, 2], [211, 127, 3], [206, 127, 3], [201, 127, 5], [194, 127, 8], [186, 128, 13], [177, 129, 21], [169, 129, 28], [161, 130, 46], [150, 129, 84], [138, 129, 124], [130, 129, 146], [125, 130, 159], [120, 130, 171], [115, 130, 180], [109, 132, 183], [102, 133, 181], [95, 135, 175], [88, 137, 167], [81, 139, 157], [74, 140, 146], [65, 142, 131], [55, 144, 114], [44, 147, 95], [35, 149, 72], [27, 148, 45], [22, 140, 26], [19, 125, 19], [15, 129, 15]]
PAL_DN = [[8, 131, 7], [13, 136, 11], [20, 135, 15], [24, 126, 17], [31, 121, 23], [38, 121, 33], [43, 128, 41], [51, 139, 57], [63, 142, 88], [73, 136, 112], [79, 130, 127], [85, 132, 144], [92, 135, 160], [100, 135, 173], [106, 134, 182], [113, 136, 168], [119, 137, 152], [125, 134, 173], [130, 131, 190], [137, 130, 178], [145, 128, 159], [153, 129, 136], [160, 130, 114], [168, 131, 88], [178, 132, 55], [186, 133, 32], [192, 133, 21], [200, 132, 13], [210, 130, 6], [218, 128, 3], [225, 129, 2], [231, 129, 1], [233, 129, 1], [230, 130, 1], [220, 132, 2], [210, 134, 3], [215, 134, 2], [218, 133, 1], [210, 135, 2], [199, 136, 3], [192, 137, 5], [185, 137, 7], [178, 137, 10], [172, 138, 14], [165, 138, 19], [161, 139, 27], [152, 140, 39], [138, 140, 61], [130, 141, 81], [124, 142, 91], [114, 143, 96], [104, 143, 96], [94, 144, 95], [89, 144, 102], [84, 143, 111], [78, 143, 117], [71, 144, 117], [61, 145, 106], [53, 145, 96], [47, 144, 86], [38, 145, 68], [30, 142, 50], [21, 134, 30], [11, 130, 12]]
MAPHEX = ""
YS = [1138, 512, 512, 256, 576, 384, 384, 256, 960, 256, 512, 256, 480, 256, 384, 256]
WW = [720, 1920, 1920, 1920, 720, 1280, 1280, 1920, 720, 1920, 1920, 1920, 720, 1920, 1280, 1920]


def clamp(v, a, b):
    return a if v < a else b if v > b else v


def hw8(r, g, b, kcb=1.0):
    """rgb 0..255 -> 8-bit (Y pre-boosted 16/13, Cr, Cb), hardware convention (U = Cr).  kcb pre-emphasises Cb
    (palettes: x1.08, measured to offset what the mandatory [1 2 2 2 2 2 2 2 1]/16 chroma box takes from the
    finest stripes at 1080)."""
    r, g, b = r / 255.0, g / 255.0, b / 255.0
    y = 0.299 * r + 0.587 * g + 0.114 * b
    cb = (b - y) / 1.772 * kcb; cr = (r - y) / 1.402
    y10 = 64 + y * 876; u10 = 512 + cr * 896; v10 = 512 + cb * 896
    y10 = 64 + (y10 - 64) * 16.0 / 13.0
    return (clamp(int(round(y10 / 4)), 0, 255), clamp(int(round(u10 / 4)), 0, 255), clamp(int(round(v10 / 4)), 0, 255))


def tri(t):
    t = t % 1.0
    return 1 - abs(2 * t - 1)


def pal_rgb(k, half, i):
    """palette k, half (0 above / 1 below the horizon), phase step i (0..63): rgb.  0 = Warp (the fitted photo
    palettes); 1..7 are transforms of it, so every palette keeps the photo's full-cycle stripe structure."""
    R, G, B = (PAL_UP if half == 0 else PAL_DN)[i]
    Y = 0.299 * R + 0.587 * G + 0.114 * B
    if k == 0: return R, G, B              # Warp
    if k == 1: return R, 0.45 * G + 0.2 * R, 0.25 * B          # Ember
    if k == 2: return 0.7 * B, G, R                             # Ice
    if k == 3: return G, R, B                                   # Toxic
    if k == 4: return R, 0.75 * B, G                            # Candy
    if k == 5: return Y, Y, Y                                   # Mono
    if k == 6: return B, R, G                                   # Neon
    return 0.9 * R, 0.55 * G + 0.15 * R, 0.3 * B                # Rust


def tables():
    pal = [hw8(*[clamp(v, 0, 255) for v in pal_rgb(k, h, i)], kcb=1.08) for k in range(8) for h in range(2) for i in range(64)]
    hz_pts = [(0, 146), (420, 146), (540, 140), (660, 128), (760, 104), (1000, 96), (1080, 84)]

    def interp(pts, v):
        for (a, fa), (b, fb) in zip(pts, pts[1:]):
            if a <= v <= b:
                return fa + (fb - fa) * (v - a) / float(b - a)
        return pts[-1][1]
    hz = [int(round(146 - interp(hz_pts, 32 * i + 16))) for i in range(34)]
    ed_pts = [(0, 212), (520, 205), (540, 160), (560, 143), (600, 129), (640, 119), (660, 106), (680, 75), (700, 35),
              (740, 27), (1080, 20)]
    ed = [int(interp(ed_pts, 16 * i + 8)) // 4 for i in range(68)]

    def sm(t):
        t = clamp(t, 0, 1); return t * t * (3 - 2 * t)
    mg = [hw8(0, 112 * sm((4 * i + 2 - 50) / 150.0), 0) for i in range(64)]
    ka = [int(round(2 ** ((16 * i - 512) / 512.0) * 2 ** 32 / 60000)) for i in range(64)]
    kb = [int(round(2 ** ((16 * i - 512) / 512.0) * 2 ** 32 / 96000)) for i in range(64)]
    tim = []
    for i in range(16):
        sd = WW[i] == 720
        sx = {720: 32, 1280: 24, 1920: 16}[WW[i]]
        tim.append(dict(ys=YS[i], sx=sx, x0=240 * 16 if sd else 0, vp=334 if sd else 94,
                        oxi=int(round(sx * 65536 / 10240.0)), zi=int(round(YS[i] * 65536 / 24.0 / 256))))
    m = [int(ch, 16) for ch in MAPHEX]
    me = [0] * 8192; mo = [0] * 8192
    for r in range(136):
        for c in range(120):
            if r % 2 == 0: me[(r // 2) * 120 + c] = m[r * 120 + c]
            else: mo[(r // 2) * 120 + c] = m[r * 120 + c]
    return dict(pal=pal, hz=hz, ed=ed, mg=mg, ka=ka, kb=kb, tim=tim, me=me, mo=mo)


def arr(name, typ, vals, w):
    rows = []
    for i in range(0, len(vals), 32):
        rows.append("        " + ", ".join('"' + format(v & ((1 << w) - 1), "0" + str(w) + "b") + '"' for v in vals[i:i + 32]))
    return "    constant " + name + " : " + typ + " := (\n" + ",\n".join(rows) + "\n    );"


def emit():
    t = tables()
    cs = []
    cs.append(arr("C_ME", "t_map", t["me"], 4))
    cs.append(arr("C_MO", "t_map", t["mo"], 4))
    for k, nm in ((0, "Y"), (1, "U"), (2, "V")):
        cs.append(arr("C_PAL_" + nm, "t_pal", [e[k] for e in t["pal"]], 8))
        cs.append(arr("C_MG_" + nm, "t_mg", [e[k] for e in t["mg"]], 8))
    cs.append(arr("C_HZ", "t_hz", t["hz"], 6))
    cs.append(arr("C_ED", "t_ed", t["ed"], 6))
    cs.append(arr("C_KA", "t_k", t["ka"], 18))
    cs.append(arr("C_KB", "t_k", t["kb"], 18))
    for key, w in (("ys", 11), ("sx", 6), ("x0", 13), ("vp", 9), ("oxi", 8), ("zi", 14)):
        cs.append(arr("C_T_" + key.upper(), "t_tim" + str(w), [e[key] for e in t["tim"]], w))
    typs = ("    type t_map is array (0 to 8191) of std_logic_vector(3 downto 0);\n"
            "    type t_pal is array (0 to 1023) of std_logic_vector(7 downto 0);\n"
            "    type t_mg is array (0 to 63) of std_logic_vector(7 downto 0);\n"
            "    type t_hz is array (0 to 33) of std_logic_vector(5 downto 0);\n"
            "    type t_ed is array (0 to 67) of std_logic_vector(5 downto 0);\n"
            "    type t_k is array (0 to 63) of std_logic_vector(17 downto 0);\n")
    for w in (11, 6, 13, 9, 8, 14):
        typs += "    type t_tim%d is array (0 to 15) of std_logic_vector(%d downto 0);\n" % (w, w - 1)
    src = ("-- Generated by warp.py -- do not edit.\nlibrary ieee;\nuse ieee.std_logic_1164.all;\n\n"
           "package warp_pkg is\n" + typs + "\n".join(cs) + "\nend package warp_pkg;\n")
    with open(os.path.join(HERE, "warp_pkg.vhd"), "w") as f:
        f.write(src)


if __name__ == "__main__":
    emit()
